import {GOALS,buildPlan,validatePreferences} from './planner.js';
import {dateKey,daysBetween} from './engine.js';
import {bodyArt} from './fitness.js';

const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const addDays=(key,n)=>{const d=new Date(key+'T12:00:00');d.setDate(d.getDate()+n);return dateKey(d);};
const titles=['GOAL','KNOW YOUR BODY','WORKOUT PREFERENCE','FITNESS ASSESSMENT'];
export const SETUP_STEPS=['gender','motivation','goal','focus','height','weight','target','birth','body-info','timeframe','location','days','injuries','equipment','minutes','level','cardio','flexibility','pacing','feelings','reward','name','metric','guidance','review'];
const chapters=id=>SETUP_STEPS.indexOf(id)<4?0:SETUP_STEPS.indexOf(id)<10?1:SETUP_STEPS.indexOf(id)<15?2:3;

export function initOnboarding(win,api){
 const doc=win.document,abort=new win.AbortController(),key=api.draftKey||'form-seven.setup.v1';
 const layer=doc.createElement('section');layer.id='entry-flow';layer.className='entry-flow';layer.hidden=true;layer.setAttribute('aria-label','Welcome and personal plan setup');doc.body.append(layer);
 let route='',step=0,draft=null,editing=false,busy=false,unit='kg',heightUnit='cm',historySteps=[],previousRoute='home',resetCredentials=null,pendingConfirmation=null;
 const chrome=[...doc.querySelectorAll('.sidebar,.app-shell,.bottom-nav,.skip-link')];
 const on=(name,fn)=>layer.addEventListener(name,fn,{signal:abort.signal});
 function setVisible(visible){layer.hidden=!visible;doc.body.classList.toggle('in-entry-flow',visible);for(const el of chrome){el.hidden=visible;el.inert=visible;}doc.documentElement.dataset.setupOpen=String(visible);if(visible)api.pause?.();}
 function hash(value){try{win.history.replaceState(null,'','#'+value);}catch{}}
 function focus(){win.scrollTo?.({top:0,behavior:'instant'});layer.querySelector('h1')?.focus({preventScroll:true});}
 function error(message){const e=layer.querySelector('#flow-error');if(e)e.textContent=message;}
 function saveDraft(){try{win.localStorage.setItem(key,JSON.stringify({version:1,profile:draft,step,editing,stamp:Date.now()}));}catch{error('Setup could not be saved on this device. Keep this page open until you finish.');}}
 function readDraft(){try{const x=JSON.parse(win.localStorage.getItem(key));if(x?.version!==1||!x.profile||Array.isArray(x.profile)||!Number.isInteger(x.step)||x.step<0||x.step>=SETUP_STEPS.length||!Number.isFinite(x.stamp)||x.stamp>Date.now()+60000)return null;const p={heightCm:null,...api.getState().profile};const choices={gender:['male','female','other','prefer-not-to-say'],motivation:['tone','confidence','energy','health','stress',null],goalType:Object.keys(GOALS),experience:['beginner','intermediate','advanced'],ageBand:['teen','adult','older'],coaching:['quiet','supportive'],location:['home','gym','outdoors'],cardioComfort:['out-of-breath','mild','easy',null],flexibility:['far','near','touch',null],reward:['clothes','meal','gift','trip','photos','none']};const arrays={focusAreas:['full','abs','chest','arms','core','back','glutes','legs'],days:[0,1,2,3,4,5,6],restrictions:['no-floor','knee','wrist','shoulder','back'],equipment:['none','chair','wall'],feelings:['confidence','body','achievement','energy','health']};for(const field of Object.keys(p)){const value=x.profile[field];if(value===undefined)continue;if(choices[field]){if(choices[field].includes(value))p[field]=value;}else if(arrays[field]){if(Array.isArray(value)&&value.length<=8&&value.every(v=>arrays[field].includes(v))&&new Set(value).size===value.length)p[field]=[...value];}else if(['heightCm','startWeight','targetValue','birthYear','baselineValue','goalLoss','sessionMinutes','durationWeeks'].includes(field)){if(value===null||typeof value==='number'&&Number.isFinite(value)&&Math.abs(value)<=100000)p[field]=value;}else if(typeof p[field]==='boolean'&&typeof value==='boolean')p[field]=value;else if(typeof p[field]==='string'&&typeof value==='string'&&value.length<100&&!/[\u0000-\u001f<>]/.test(value))p[field]=value;}if(!GOALS[p.goalType].units.includes(p.targetUnit))p.targetUnit=GOALS[p.goalType].defaultUnit;return {...x,profile:p};}catch{}return null;}
 function clearDraft(){try{win.localStorage.removeItem(key);}catch{}}
 function welcome(){route='welcome';setVisible(true);hash('welcome');const saved=readDraft();layer.innerHTML=`<div class="welcome-screen"><div class="welcome-photo" role="img" aria-label="Two adults getting ready to exercise at home"></div><a class="welcome-brand" href="#welcome">FORM<span>HOME WORKOUT</span></a><div class="welcome-copy"><span class="welcome-kicker">YOUR HOME. YOUR PACE.</span><h1 tabindex="-1">TAILORED<br>JUST FOR YOU.</h1><p>Build strength, move better, feel confident.<br>A plan that fits your life.</p><button class="flow-green" data-entry="${api.auth?.requiresAccounts||api.auth?.configured?'signup':'guest'}">LET’S GO! <span aria-hidden="true">→</span></button><button class="welcome-login" data-entry="login">${api.auth?.requiresAccounts||api.auth?.configured?'Already have an account? <strong>Log in</strong>':'Your device profile'}</button>${!api.auth?.requiresAccounts||api.getState().profile.onboardingComplete?`<button class="welcome-guest" data-entry="${api.auth?.requiresAccounts?'continue-device':'guest'}">${api.auth?.requiresAccounts?'Use existing device records':saved?'Resume setup on this device':'Continue on this device'}</button>`:''}<small>${api.auth?.requiresAccounts?'Sign up to save your plan and track progress across devices.':'Saved on this device. No password needed.'}</small></div></div>`;focus();}
 function deviceScreen(){route='device';setVisible(true);hash('device');const p=api.getState().profile;layer.innerHTML=`<div class="auth-screen"><button class="flow-back" data-entry="return-device" aria-label="Back">←</button><a class="auth-brand" href="#welcome" data-entry="return-device">FORM</a><h1 tabindex="-1">Your device profile</h1><p>${p.onboardingComplete?`Welcome back${p.name?', '+esc(p.name):''}. Your plan and progress are saved in this browser.`:'Create a personal plan without an account or password.'}</p><div class="flow-callout">Your profile works offline after FORM finishes caching. Use the same browser or installed PWA to return to your records.</div><button class="flow-black" data-entry="continue-device">${p.onboardingComplete?'Continue my plan':'Create my plan'}</button>${p.onboardingComplete?'<button class="flow-link" data-entry="edit-device">Edit my profile</button>':''}<p class="auth-note">Use Export backup in Profile before changing phones or clearing browser storage. Restore the backup on your new device.</p><a class="flow-link" href="./privacy.html" target="_blank" rel="noopener">Privacy & data</a></div>`;focus();}
 function authScreen(kind){if(!api.auth?.configured&&!api.auth?.requiresAccounts){deviceScreen();return;}route=kind;setVisible(true);hash(kind);const signup=kind==='signup',reset=kind==='reset';layer.innerHTML=`<div class="auth-screen"><button class="flow-back" data-entry="welcome" aria-label="Back to welcome">←</button><a class="auth-brand" href="#welcome" data-entry="welcome">FORM</a><h1 tabindex="-1">${reset?'Reset your password':signup?'Create your account':'Welcome back'}</h1><p>${reset?'Enter your account email to request a reset link.':signup?'Start a routine made for you.':'Sign in to your FORM account.'}</p><form id="entry-auth"><label>Email<input name="email" type="email" autocomplete="email" required maxlength="254"></label>${reset?'':`${signup?'<label>Your name (optional)<input name="name" autocomplete="name" maxlength="80"></label>':''}<label>Password<input name="password" type="password" autocomplete="${signup?'new-password':'current-password'}" ${signup?'minlength="10"':''} required maxlength="256"></label>`}${signup?'<label>Confirm password<input name="confirmPassword" type="password" autocomplete="new-password" minlength="10" required maxlength="256"></label><label class="flow-consent"><input name="trackingConsent" type="checkbox" required> I agree to store my training progress and let the FORM owner monitor my workout activity and goals. Optional body measurements are not shown in the owner dashboard.</label>':''}<p id="flow-error" class="flow-error" role="alert">${api.auth?.configured?'':'The account server is not connected at this address yet.'}</p><button type="submit" class="flow-black" ${api.auth?.configured?'':'disabled'}>${reset?'Send reset link':signup?'Sign up':'Log in'}</button></form>${!reset&&api.auth.googleEnabled?'<button class="google-signin" data-entry="google">Continue with Google</button>':''}<button class="flow-link" data-entry="${signup?'login':'signup'}">${signup?'Already have an account? Log in':'Create an account'}</button>${!signup&&!reset?'<button class="flow-link" data-entry="reset">Forgot password?</button>':''}${api.auth?.requiresAccounts?'':'<div class="auth-divider">OR</div><button class="flow-outline" data-entry="guest">Continue on this device</button>'}<p class="auth-note">Your signed-in progress is saved to your account. The app keeps a device copy for offline workouts and syncs when you reconnect.</p><a class="flow-link" href="./privacy.html" target="_blank" rel="noopener">Privacy & data</a></div>`;focus();}
 function emailConfirmation(value){pendingConfirmation={...value};route='email-confirmation';setVisible(true);hash('confirm-email');const linked=!!pendingConfirmation.token;layer.innerHTML=`<div class="auth-screen"><a class="auth-brand">FORM</a><h1 tabindex="-1">${linked?'Confirm your sign-in':'Check your email'}</h1><p>${linked?'Use the button below to confirm your email and sign in.':'Open the confirmation link sent to '+esc(pendingConfirmation.maskedEmail||'your email address')+'.'}</p><div class="flow-callout">Confirmation links expire after 15 minutes and can be used once. You can request a new link if needed.</div>${linked?'<button class="flow-green" data-entry="email-confirm">Confirm & sign in</button>':'<button class="flow-black" data-entry="email-check">I’ve confirmed my email</button>'}<p id="flow-error" class="flow-error" role="alert"></p><button class="flow-link" data-entry="email-resend">Resend confirmation email</button><button class="flow-link" data-entry="login">Back to log in</button></div>`;focus();}
 async function confirmationAction(action){if(!pendingConfirmation)return;busy=true;api.accountOperation?.(true);try{if(action==='email-resend'){const next=await api.auth.resendConfirmation(pendingConfirmation.challengeId);emailConfirmation({...next,expectedEmail:pendingConfirmation.expectedEmail});error('A new confirmation link was requested. Check your inbox and spam folder.');}else if(action==='email-confirm'){await api.auth.confirmEmail(pendingConfirmation.challengeId,pendingConfirmation.token);pendingConfirmation=null;await api.sessionChanged?.();}else{await api.auth.ready();const user=api.auth.getSession();if(!user||!user.emailVerified||pendingConfirmation.expectedEmail&&user.email?.toLowerCase()!==pendingConfirmation.expectedEmail.toLowerCase())throw new Error('Email confirmation is not complete for this account yet. Open the newest email link, then try again.');pendingConfirmation=null;await api.sessionChanged?.();}}catch(e){error(e.message);}finally{api.accountOperation?.(false);busy=false;}}
 function loading(){route='loading';setVisible(true);layer.innerHTML='<div class="auth-screen"><a class="auth-brand">FORM</a><h1 tabindex="-1">Opening your progress…</h1><p>Checking the saved plan for your account.</p></div>';focus();}
 function passwordReset({uid,token}){resetCredentials={uid,token};route='reset-confirm';setVisible(true);hash('reset-confirm?'+new URLSearchParams({uid,token}));layer.innerHTML='<div class="auth-screen"><h1 tabindex="-1">Choose a new password</h1><form id="entry-auth"><label>New password<input name="password" type="password" autocomplete="new-password" minlength="10" maxlength="256" required></label><label>Confirm password<input name="confirmPassword" type="password" autocomplete="new-password" minlength="10" maxlength="256" required></label><p id="flow-error" class="flow-error" role="alert"></p><button class="flow-black" type="submit">Save password</button></form><button class="flow-link" data-entry="login">Back to log in</button></div>';focus();}
 function begin({edit=false,preset={},resume=true}={}){editing=edit;previousRoute=win.location.hash.slice(1)||'home';const saved=resume?readDraft():null;draft={heightCm:null,...api.getState().profile,...preset};if(saved&&saved.editing===edit&&!Object.keys(preset).length){draft=saved.profile;step=saved.step;}else step=0;historySteps=[];setVisible(true);render();saveDraft();}
 function options(field,items,multi=false){const current=draft[field];return `<div class="answer-options" role="${multi?'group':'radiogroup'}" aria-label="${esc(field)}">${items.map(([value,label,detail,art])=>{const chosen=multi?current?.includes(value):current===value;return `<button type="button" class="answer-card ${chosen?'selected':''} ${art?'visual-answer':''}" data-choice="${field}" data-value="${value}" ${multi?'aria-pressed':'aria-checked'}="${chosen}" ${multi?'':'role="radio"'}>${art?`<span class="answer-art">${bodyArt(art)}</span>`:''}<span><strong>${esc(label)}</strong>${detail?`<small>${esc(detail)}</small>`:''}</span><span class="answer-check" aria-hidden="true">${chosen?'✓':''}</span></button>`;}).join('')}</div>`;}
 function number(field,label,value,min,max,stepSize=1){return `<label class="flow-number-label">${label}<input class="flow-number" data-field="${field}" type="number" value="${value??''}" min="${min}" max="${max}" step="${stepSize}" inputmode="decimal" aria-label="${label}"></label><div class="ruler-art" aria-hidden="true"></div>`;}
 function optional(){return '<p class="flow-hint">Optional. Leave blank to continue without this measurement.</p>';}
 function content(id){
  const adult=draft.ageBand!=='teen';
  switch(id){
   case 'gender':return ['Tell us your gender','Personalize your profile. Everyone can choose their own goals.',options('gender',[['male','Male',null,'full'],['female','Female',null,'glutes'],['other','Others'],['prefer-not-to-say','Prefer not to answer']])];
   case 'motivation':return ['What motivates you the most?','Let’s start with what matters to you.',options('motivation',[['tone','Get toned'],['confidence','Become confident'],['energy','Boost energy'],['health','Improve health'],['stress','Release stress']])];
   case 'goal':return ['What is your main target?','Choose the direction for your personal plan.',options('goalType',[...(adult?[['weight','Manage my weight'],['curves','Figure 8 / glutes & core','Build glutes and core; appearance varies.'],['abs','Six-pack & core strength','Train abdominal strength; visible definition varies.']]:[]),['strength','Build muscle & strength'],['conditioning','Keep fit'],['core','Strengthen my core'],['cardio','Improve endurance'],['mobility','Move more comfortably'],['consistency','Build a lasting habit'],['test','Reach a performance goal']])];
   case 'focus':return ['Choose your focus area','Select the areas you’d like to train. Your plan still includes balanced movement.',`<div class="focus-body">${bodyArt(draft.focusAreas.includes('glutes')?'glutes':'full')}</div>${options('focusAreas',[['chest','Chest'],['arms','Arms'],['abs','Belly & core'],['glutes','Glutes'],['legs','Legs'],['back','Back'],['full','Full body']],true)}`];
   case 'height':return ['How tall are you?','A measurement for your optional body journal.',`<div class="unit-switch"><button data-unit="cm" aria-pressed="${heightUnit==='cm'}">cm</button><button data-unit="in" aria-pressed="${heightUnit==='in'}">ft / in</button></div>${number('heightCm',heightUnit==='cm'?'Height (cm)':'Height (total inches)',draft.heightCm==null?null:heightUnit==='cm'?draft.heightCm:Math.round(draft.heightCm/2.54*10)/10,heightUnit==='cm'?100:39.4,heightUnit==='cm'?250:98.4,.1)}${optional()}`];
   case 'weight':return ['What is your current weight?','You can train without tracking your weight.',`<div class="unit-switch"><button data-unit="kg" aria-pressed="${unit==='kg'}">kg</button><button data-unit="lb" aria-pressed="${unit==='lb'}">lbs</button></div>${number('startWeight',unit==='kg'?'Weight (kg)':'Weight (lbs)',draft.startWeight==null?null:unit==='kg'?draft.startWeight:Math.round(draft.startWeight*2.2046226218*10)/10,unit==='kg'?30:66.1,unit==='kg'?400:881.8,.1)}${optional()}`];
   case 'target':return ['What is your target weight?','An optional personal target. Your timeframe can be changed later.',`<div class="unit-switch"><button data-unit="kg" aria-pressed="${unit==='kg'}">kg</button><button data-unit="lb" aria-pressed="${unit==='lb'}">lbs</button></div>${number('targetValue',unit==='kg'?'Target (kg)':'Target (lbs)',draft.targetValue==null?null:unit==='kg'?draft.targetValue:Math.round(draft.targetValue*2.2046226218*10)/10,unit==='kg'?30:66.1,unit==='kg'?400:881.8,.1)}${optional()}<p class="flow-callout">Weight targets are preferences, not a forecast. Fitness and body changes take different amounts of time for different people.</p>`];
   case 'birth':return ['When were you born?','Your age group helps us show suitable plan options.',`${number('birthYear','Birth year (optional)',draft.birthYear,new Date().getFullYear()-100,new Date().getFullYear()-16)}${options('ageBand',[['teen','16–17'],['adult','18–64'],['older','65+']])}<p class="flow-hint">Choose your age group even if you prefer to leave the year blank.</p>`];
   case 'body-info':return ['Small steps. Stronger you.','Training can build strength, stamina and confidence.',`<div class="info-body">${bodyArt(draft.goalType==='curves'?'glutes':'full')}</div><p class="flow-callout">${draft.goalType==='curves'?'Glute and core training supports muscle development. Exercise cannot selectively burn belly fat or guarantee a “Figure 8” shape.':draft.goalType==='abs'?'Core practice builds strength and control. Visible abs depend on body composition and genetics; abdominal exercises cannot selectively burn belly fat.':'Your plan progresses through practice and recovery. Body shape and weight changes vary; consistency is something you can track.'}</p>`];
   case 'timeframe':return ['What timeframe works for you?','Set a training window you can review and extend.',`<div class="answer-options timeframe-options">${[2,4,8,12,24,52].map(n=>`<button class="answer-card ${daysBetween(draft.startDate,draft.deadline)===n*7?'selected':''}" data-weeks="${n}"><strong>${n} weeks</strong></button>`).join('')}</div><label class="flow-input-label">Start date<input type="date" data-field="startDate" value="${esc(draft.startDate)}"></label><label class="flow-input-label">Goal date<input type="date" data-field="deadline" min="${addDays(draft.startDate,14)}" max="${addDays(draft.startDate,3653)}" value="${esc(draft.deadline)}"></label><p class="flow-hint">From 2 weeks to a custom date within 10 years. This is your schedule, not a promised result date.</p>`];
   case 'location':return ['Where do you usually exercise?','Train in a place that works for you.',options('location',[['gym','Gym'],['home','Home'],['outdoors','Outdoors']])];
   case 'days':return ['How often would you like to work out?','Choose your training days. Recovery days are part of the plan.',`<div class="frequency-presets">${[1,2,3,4,5,6,7].map(n=>`<button data-frequency="${n}" aria-pressed="${draft.days.length===n}">${n===7?'Every day':n+' '+(n===1?'day':'days')+' / week'}</button>`).join('')}</div><h2 class="question-subtitle">Which days work for you?</h2><div class="weekday-options">${['S','M','T','W','T','F','S'].map((n,i)=>`<button data-day="${i}" aria-label="${['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'][i]}" aria-pressed="${draft.days.includes(i)}">${n}</button>`).join('')}</div>`];
   case 'injuries':return ['Any movements you need to avoid?','Select sensitive areas or movements. This does not assess or treat an injury.',`${options('restrictions',[['none','No movement restrictions'],['shoulder','Shoulder'],['back','Back / waist'],['wrist','Wrist'],['knee','Knee'],['no-floor','Getting down to the floor']],true)}<button class="flow-toggle" data-boolean="lowImpact" aria-pressed="${draft.lowImpact}">Low-impact movement <span>${draft.lowImpact?'On':'Off'}</span></button><p class="flow-hint">For a recent injury, ask a qualified clinician which exercise is appropriate before training.</p>`];
   case 'equipment':return ['What can you use?','Our routines use bodyweight and simple support.',options('equipment',[['none','No equipment'],['chair','A stable chair'],['wall','A clear wall']],true)];
   case 'minutes':return ['How much time do you have?','Warm-up, rest and cooldown are included.',options('sessionMinutes',[[10,'10 minutes'],[15,'15 minutes'],[20,'20 minutes'],[30,'30 minutes'],[45,'45 minutes'],[60,'60 minutes']])];
   case 'level':return ['What is your fitness level?','Choose the level that feels right today.',options('experience',[['beginner','Beginner','I’m new to fitness!'],['intermediate','Intermediate','I exercise regularly.'],['advanced','Advanced','Ready for more challenges!']])];
   case 'cardio':return ['How do you feel after brisk walking?','Think about a recent comfortable walk. No test is required.',options('cardioComfort',[['out-of-breath','Out of breath'],['mild','Mildly breathless'],['easy','Completely at ease'],['skip','Prefer to skip']])];
   case 'flexibility':return ['How far can you comfortably reach?','Think about a seated forward bend. Avoid forcing a stretch or testing through pain.',options('flexibility',[['far','Far from my feet'],['near','Close to my feet'],['touch','Easily touch my feet'],['skip','Prefer to skip']])];
   case 'pacing':return ['A plan that adapts with you','Your starting level is a starting point.',`<div class="info-body">${bodyArt('full')}</div><p class="flow-callout">${draft.cardioComfort==='out-of-breath'?'Start with comfortable movement and breaks. Stop if you feel unwell.':'Use a comfortable effort and controlled movement.'} After each workout, your effort, soreness and difficulty feedback help adjust upcoming sessions.</p><div class="plan-benefits"><span>✓ Time that fits your day</span><span>✓ Movement choices you control</span><span>✓ Recovery and progress checks</span></div>`];
   case 'feelings':return ['How do you want to feel?','Choose all that matter to you.',options('feelings',[['confidence','Feel confident'],['body','Be comfortable in my body'],['achievement','Be proud of myself'],['energy','Be energized'],['health','Support my health']],true)];
   case 'reward':return ['How will you celebrate?','Choose a reward for showing up for yourself.',options('reward',[['clothes','Buy new clothes'],['meal','Enjoy a tasty meal'],['gift','Buy a special gift'],['trip','Go on a trip'],['photos','Take photos'],['none','I’ll decide later']])];
   case 'name':return ['What should we call you?','Make your training space feel like yours.',`<label class="flow-input-label">Your name (optional)<input data-field="name" autocomplete="given-name" maxlength="80" value="${esc(draft.name)}" placeholder="Your name"></label>`];
   case 'metric':return ['Would you like a measurable target?','Optional. You can train without a number.',`<p class="flow-callout">${esc(GOALS[draft.goalType].description)}</p><label class="flow-input-label">Starting assessment (${esc(draft.targetUnit)})<input type="number" data-field="baselineValue" min="0" max="10000" step="${['reps','sessions'].includes(draft.targetUnit)?1:.1}" value="${draft.baselineValue}"></label><label class="flow-input-label">Target (${esc(draft.targetUnit)}, optional)<input type="number" data-field="targetValue" min="0" max="10000" step="${['reps','sessions'].includes(draft.targetUnit)?1:.1}" value="${draft.targetValue??''}"></label><p class="flow-hint">Assessments are values you record yourself; workout duration does not become a repetition score.</p>`];
   case 'guidance':return ['Train at your own pace','A little care helps make your routine sustainable.',`<div class="guidance-list"><p>Warm up, use controlled movement and take extra rest whenever needed.</p><p>Stop for pain, dizziness, chest discomfort or unusual breathlessness. Seek appropriate medical advice if symptoms persist.</p><p>This app provides general fitness guidance. Ask a qualified clinician about injuries, pregnancy or other exercise concerns.</p></div><label class="flow-consent"><input type="checkbox" data-field="safetyAccepted" ${draft.safetyAccepted?'checked':''}> I understand and will exercise within my ability.</label><label class="flow-consent"><input type="checkbox" data-field="trackMeasurements" ${draft.trackMeasurements?'checked':''} ${adult?'':'disabled'}> Enable optional adult body measurements</label>`];
   case 'review':{const plan=buildPlan(validatePreferences(draft)),first=plan.sessions.slice(0,7),weeks=Math.ceil(daysBetween(draft.startDate,draft.deadline)/7);return ['Your personal plan is ready',`${esc(GOALS[draft.goalType].title)} · ${weeks} weeks`, `<div class="plan-preview-art">${bodyArt(draft.goalType==='curves'?'glutes':draft.focusAreas[0])}</div><div class="preview-stats"><div><small>FOCUS</small><strong>${draft.focusAreas.map(x=>x==='abs'?'Core':x.charAt(0).toUpperCase()+x.slice(1)).join(', ')}</strong></div><div><small>LEVEL</small><strong>${esc(draft.experience)}</strong></div><div><small>DURATION</small><strong>${draft.sessionMinutes} min</strong></div><div><small>PER WEEK</small><strong>${draft.days.length} days</strong></div></div><h2 class="question-subtitle">Your first training days</h2><div class="preview-schedule">${first.map(s=>`<div><span>${new Date(s.date+'T12:00:00').toLocaleDateString(undefined,{weekday:'short',month:'short',day:'numeric'})}</span><strong>${esc(s.session.title)}</strong><small>${s.session.minutes??draft.sessionMinutes} min</small></div>`).join('')}</div><p class="flow-callout">${esc(draft.startDate)} → ${esc(draft.deadline)}<br>This preview shows your training schedule. Results vary; review your goal as you learn.</p>`];}
  }
 }
 function visibleStep(i){const id=SETUP_STEPS[i];return !(id==='target'&&draft.goalType!=='weight')&&!(id==='metric'&&draft.goalType==='weight')&&!(['height','weight','target'].includes(id)&&draft.ageBand==='teen');}
 function render(stay=false){const savedScroll=win.scrollY||0;const active=doc.activeElement;const retain=active?.dataset.choice?`[data-choice="${active.dataset.choice}"][data-value="${active.dataset.value}"]`:active?.dataset.day!==undefined?`[data-day="${active.dataset.day}"]`:null;route='setup';const id=SETUP_STEPS[step],chapter=chapters(id);let parts;try{parts=content(id);}catch(e){parts=['Review your movement choices','Some choices need adjusting before your plan is ready.',`<p class="flow-error" role="alert">${esc(e.message)}</p><button class="flow-outline" data-action="review-choices">Review movement & equipment</button>`];}const current=SETUP_STEPS[step];hash('setup/'+current);layer.innerHTML=`<div class="setup-screen" data-step="${current}"><header class="setup-header"><button class="flow-back" data-action="back" aria-label="Back">←</button><div class="chapter-track">${titles.map((t,i)=>`<div class="${i<=chapter?'reached':''} ${i===chapter?'current':''}"><span>0${i+1}</span><small>${t}</small></div>`).join('')}</div>${editing?'<button class="flow-cancel" data-action="cancel">Cancel</button>':''}<div class="setup-progress"><span style="width:${(step+1)/SETUP_STEPS.length*100}%"></span></div></header><main class="question-content"><p class="question-count">${step+1} / ${SETUP_STEPS.length}</p><h1 tabindex="-1">${parts[0]}</h1><p class="question-caption">${parts[1]}</p><div class="question-answer">${parts[2]}</div><p id="flow-error" class="flow-error" role="alert"></p></main><footer class="setup-footer"><button class="${current==='review'?'flow-green':'flow-black'}" data-action="next">${current==='review'?'GET MY PLAN':'Next'} <span aria-hidden="true">→</span></button></footer></div>`;if(stay){win.scrollTo?.({top:savedScroll,behavior:'instant'});if(retain)layer.querySelector(retain)?.focus({preventScroll:true});}else focus();}
 function checkCurrent(){const id=SETUP_STEPS[step];if(id==='birth'){if(draft.birthYear!==null){const age=new Date().getFullYear()-draft.birthYear;if(!Number.isInteger(draft.birthYear)||age<16||age>100)throw new Error('Enter a year for an age between 16 and 100, or leave it blank.');draft.ageBand=age<18?'teen':age>=65?'older':'adult';}if(draft.ageBand==='teen'&&['curves','weight','abs'].includes(draft.goalType))throw new Error('For ages 16–17, go Back and choose a fitness, strength or movement goal.');}if(id==='height'&&draft.heightCm!=null&&(draft.heightCm<100||draft.heightCm>250||!Number.isFinite(draft.heightCm)))throw new Error('Enter a height between 100 and 250 cm, or leave it blank.');if(id==='weight'&&draft.startWeight!==null&&(draft.startWeight<30||draft.startWeight>400||!Number.isFinite(draft.startWeight)))throw new Error('Enter a weight between 30 and 400 kg, or leave it blank.');if(id==='target'&&draft.targetValue!==null&&(draft.targetValue<30||draft.targetValue>400||draft.startWeight===null))throw new Error('Use a target between 30 and 400 kg and a starting weight, or leave the target blank.');if(id==='days'&&!draft.days.length)throw new Error('Choose at least one training day.');if(id==='focus'&&!draft.focusAreas.length)throw new Error('Choose at least one focus area.');if(id==='timeframe'||id==='metric')validatePreferences(draft);if(id==='guidance'&&!draft.safetyAccepted)throw new Error('Please accept the training guidance before starting.');}
 function next(){try{checkCurrent();if(SETUP_STEPS[step]==='review'){api.complete({...draft,onboardingComplete:true});clearDraft();close();return;}historySteps.push(step);do{step++;}while(step<SETUP_STEPS.length&&!visibleStep(step));if(step>=SETUP_STEPS.length)step=SETUP_STEPS.length-1;render();saveDraft();}catch(e){error(e.message);}}
 function close(){setVisible(false);route='';api.showView(editing&&['home','discover','plan','progress','settings','workout','library','pelvic'].includes(previousRoute)?previousRoute:'home');}
 function back(){if(route!=='setup'){welcome();return;}if(step===0){if(editing)close();else welcome();return;}do{step=historySteps.length?historySteps.pop():step-1;}while(step>0&&!visibleStep(step));render();saveDraft();}
 function update(field,value){draft[field]=value;if(field==='goalType'){draft.targetUnit=GOALS[value].defaultUnit;draft.targetValue=null;draft.baselineValue=0;draft.goalLoss=0;}saveDraft();}
 on('click',async event=>{const target=event.target.closest('button,[data-entry]');if(!target||busy)return;const entry=target.dataset.entry;if(entry){event.preventDefault();if(entry.startsWith('email-')){await confirmationAction(entry);return;}if(entry==='welcome')welcome();else if(entry==='guest'){if(api.auth?.requiresAccounts&&!api.auth.getSession())authScreen('signup');else begin();}else if(entry==='continue-device'){if(api.getState().profile.onboardingComplete){api.continueDevice?.();close();}else begin();}else if(entry==='edit-device')begin({edit:true,resume:false});else if(entry==='return-device'){if(api.getState().profile.onboardingComplete)close();else welcome();}else if(entry==='google'){busy=true;target.disabled=true;api.accountOperation?.(true);try{await api.auth.signInGoogle();await api.sessionChanged?.();}catch(e){error(e.message);}finally{api.accountOperation?.(false);busy=false;target.disabled=false;}}else authScreen(entry);return;}if(target.dataset.action==='next'){next();return;}if(target.dataset.action==='back'){back();return;}if(target.dataset.action==='cancel'){close();return;}if(target.dataset.action==='review-choices'){step=SETUP_STEPS.indexOf('injuries');render();saveDraft();return;}if(target.dataset.choice){const f=target.dataset.choice,v=f==='sessionMinutes'?Number(target.dataset.value):target.dataset.value;if(['focusAreas','feelings','equipment','restrictions'].includes(f)){let values=[...draft[f]];if(v==='none')values=f==='restrictions'?[]:['none'];else{values=values.filter(x=>x!=='none');if(values.includes(v))values=values.filter(x=>x!==v);else values.push(v);if(f==='focusAreas'&&v==='full')values=['full'];else if(f==='focusAreas')values=values.filter(x=>x!=='full');if(f==='equipment'&&!values.length)values=['none'];}update(f,values);}else update(f,v==='skip'?null:v);render(true);return;}if(target.dataset.unit){if(['kg','lb'].includes(target.dataset.unit))unit=target.dataset.unit;else heightUnit=target.dataset.unit;render(true);return;}if(target.dataset.weeks){draft.deadline=addDays(draft.startDate,Number(target.dataset.weeks)*7);saveDraft();render(true);return;}if(target.dataset.frequency){const n=Number(target.dataset.frequency),order=[1,3,5,2,4,6,0];draft.days=order.slice(0,n).sort();saveDraft();render(true);return;}if(target.dataset.day!==undefined){const day=Number(target.dataset.day);draft.days=draft.days.includes(day)?draft.days.filter(d=>d!==day):[...draft.days,day].sort();saveDraft();render(true);return;}if(target.dataset.boolean){draft[target.dataset.boolean]=!draft[target.dataset.boolean];saveDraft();render(true);}});
 on('input',event=>{const el=event.target,f=el.dataset.field;if(!f||!draft)return;let v=el.type==='checkbox'?el.checked:el.value;if(el.type==='number'){v=v.trim()===''?null:Number(v);if(v!==null&&f==='heightCm'&&heightUnit==='in')v=Math.round(v*2.54*10)/10;if(v!==null&&['startWeight','targetValue'].includes(f)&&unit==='lb'&&SETUP_STEPS[step]!=='metric')v=Math.round(v/2.2046226218*10)/10;}draft[f]=v;if(f==='startWeight'&&draft.goalType==='weight')draft.baselineValue=v??0;saveDraft();});
 on('change',event=>{const el=event.target;if(el.type==='checkbox'&&el.dataset.field){draft[el.dataset.field]=el.checked;saveDraft();}});
 on('submit',async event=>{if(event.target.id!=='entry-auth')return;event.preventDefault();if(busy)return;if(!api.auth?.configured){error('The account server is not available at this address yet.');return;}busy=true;api.accountOperation?.(true);const form=event.target,button=form.querySelector('[type=submit]');button.disabled=true;const values=new win.FormData(form);try{if(route==='reset-confirm'){if(values.get('password')!==values.get('confirmPassword'))throw new Error('Your passwords do not match.');await api.auth.confirmPasswordReset({...resetCredentials,password:values.get('password')});resetCredentials=null;authScreen('login');error('Password changed. Log in to receive your email confirmation.');}else if(route==='reset'){await api.auth.resetPassword(values.get('email'));error('If this address has an eligible account, a password reset email will arrive.');}else{let challenge;if(route==='signup'){if(values.get('password')!==values.get('confirmPassword'))throw new Error('Your passwords do not match.');challenge=await api.auth.signUp(values.get('email'),values.get('password'),values.get('name')||'',values.get('trackingConsent')==='on');}else challenge=await api.auth.signIn(values.get('email'),values.get('password'));const expectedEmail=String(values.get('email')||'').trim();form.reset();emailConfirmation({...challenge,expectedEmail});}}catch(e){error(e.message);}finally{api.accountOperation?.(false);busy=false;button.disabled=false;}});

 return {welcome,begin,close,clearDraft,authScreen,passwordReset,emailConfirmation,loading,isOpen:()=>!layer.hidden,getStep:()=>route==='setup'?SETUP_STEPS[step]:route,getDraft:()=>draft?structuredClone(draft):null,dispose:()=>{abort.abort();layer.remove();}};
}

